      pt: ["Construída por volta de 800 d.C., cerca de 650 anos antes de Machu Picchu.", "Composta por 169 terraços de pedra, distribuídos por 30 hectares.", "Conhecida como 'Teyuna' pelos povos indígenas da Sierra Nevada.", "Redescoberta em 1972 por saqueadores que lhe chamaram 'Inferno Verde'.", "Requer uma caminhada de 4 a 6 dias através da densa floresta tropical."],
