      en: ["The largest fortress built by the Spanish in the Americas.", "Became a UNESCO World Heritage Site in 1984."],
      es: ["La mayor fortaleza construida por los españoles en América.", "Fue declarado Patrimonio de la Humanidad por la UNESCO en 1984."],
