      ro: ["Piramida a fost construită în perioada 500 - 1600 d.Hr.", "Situl a servit ca loc de înmormântare pentru elita indigenă locală.", "Statuia lui Sebastián de Belalcázar a stat pe vârful movilei între 1937 și 2020.", "Dărâmarea statuii în 2020 a fost un moment istoric de protest indigen.", "Situl arheologic se află în centrul orașului Popayán, capitala departamentului Cauca.", "Descoperirile arheologice includ morminte sub formă de puț și cameră laterală."],
      en: ["The mound was constructed between 500 and 1600 AD as a ceremonial site.", "It is considered the most important pre-Hispanic monument in Popayán.", "The statue of the Spanish founder was pulled down on September 16, 2020.", "Excavations revealed significant burial sites with ancient funerary urns.", "The pyramid stands as a testament to the Pubenenses indigenous culture.", "The site offers a 360-degree view of the surrounding Puracé volcano region."],
      es: ["Una pirámide prehispánica en Popayán, construida por pueblos indígenas mucho antes de la llegada de los españoles.", "Se encuentra en el estado sudamericano de Colombia.", "Región caracterizada por diversas zonas climáticas entre los Andes, el Amazonas y el Caribe.", "Accesible a través de la red nacional de carreteras y vuelos.", "Desempeña un papel en la economía y la cultura locales.", "Representativa de la diversidad del paisaje colombiano."],
      pt: ["Uma pirâmide pré-hispânica em Popayán, construída por povos indígenas muito antes da chegada dos espanhóis.", "Localizada no estado sul-americano da Colômbia.", "Região caracterizada por diversas zonas climáticas entre os Andes, a Amazônia e o Caribe.", "Acessível através da rede nacional de estradas e voos.", "Desempenha um papel na economia e cultura locais.", "Representativa da diversidade da paisagem colombiana."],
      fr: ["Une pyramide préhispanique à Popayán, construite par les peuples autochtones bien avant l'arrivée des Espagnols.", "Située dans l'État sud-américain de Colombie.", "Région caractérisée par diverses zones climatiques entre les Andes, l'Amazonie et les Caraïbes.", "Accessible via le réseau routier et aérien national.", "Joue un rôle dans l'économie et la culture locales.", "Représentative de la diversité du paysage colombien."],
