      de: ["Erbaut im Jahr 1753.", "Hatte eine hufeisenförmige Struktur, um Artilleriefeuer abzuwehren."],
      hu: ["1753-ban épült.", "Patkó alakú szerkezete volt a tüzérségi tűz kivédésére."],
