      en: ["Built in 1753", "Guarded Cartagena's southern approach", "Horseshoe-shaped defensive design", "Part of Cartagena's historic fortifications"],
      es: ["Construida en el año 1753.", "Tenía una estructura en forma de herradura para repeler el fuego de artillería."],
      pt: ["Construída em 1753.", "Tinha uma estrutura em forma de ferradura para repelir o fogo de artilharia."],
