      de: ["Auch als 'Piedras del Tunjo' bekannt.", "Einige Malereien sind über 10.000 Jahre alt."],
      hu: ["'Piedras del Tunjo' néven is ismert.", "Egyes festmények több mint 10 000 évesek."],
      ro: ["Cunoscut și sub numele de 'Piedras del Tunjo'.", "Unele picturi au peste 10.000 de ani."],
      en: ["Also known as 'Piedras del Tunjo'.", "Some paintings are over 10,000 years old."],
      es: ["También conocido como 'Piedras del Tunjo'.", "Algunas pinturas tienen más de 10.000 años de antigüedad."],
      pt: ["Também conhecido como 'Piedras del Tunjo'.", "Algumas pinturas têm mais de 10.000 anos."],
      fr: ["Également connu sous le nom de 'Piedras del Tunjo'.", "Certaines peintures ont plus de 10 000 ans."],
