      en: ["Construction took nearly 80 years (1848-1926).", "Designed by architect Thomas Reed."],
      es: ["Su construcción duró casi 80 años (1848-1926).", "Diseñado por el arquitecto Thomas Reed."],
      pt: ["A construção demorou quase 80 anos (1848-1926).", "Projetado pelo arquiteto Thomas Reed."],
